module water_robots(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] well_count,\n    input [2:0] pipe_count,\n    input [15:0] well_x_0, well_y_0,\n    input [15:0] well_x_1, well_y_1,\n    input [15:0] well_x_2, well_y_2,\n    input [15:0] well_x_3, well_y_3,\n    input [2:0] pipe_start_0, pipe_start_1, pipe_start_2, pipe_start_3,\n    input [2:0] pipe_start_4, pipe_start_5, pipe_start_6, pipe_start_7,\n    input [15:0] pipe_end_x_0, pipe_end_y_0,\n    input [15:0] pipe_end_x_1, pipe_end_y_1,\n    input [15:0] pipe_end_x_2, pipe_end_y_2,\n    input [15:0] pipe_end_x_3, pipe_end_y_3,\n    input [15:0] pipe_end_x_4, pipe_end_y_4,\n    input [15:0] pipe_end_x_5, pipe_end_y_5,\n    input [15:0] pipe_end_x_6, pipe_end_y_6,\n    input [15:0] pipe_end_x_7, pipe_end_y_7,\n    output reg result,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0]\n        IDLE        = 4'd0,\n        CAPTURE     = 4'd1,\n        INTERSECT   = 4'd2,\n        BIPARTITE   = 4'd3,\n        FINISH      = 4'd4;\n\n    reg [3:0] state, next_state;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    // Capture registers\n    reg [15:0] well_x [0:3];\n    reg [15:0] well_y [0:3];\n    reg [2:0] pipe_start [0:7];\n    reg [15:0] pipe_end_x [0:7];\n    reg [15:0] pipe_end_y [0:7];\n    reg [15:0] pipeA_x [0:7];\n    reg [15:0] pipeA_y [0:7];\n\n    // Intersection variables\n    reg [2:0] i, j;\n    reg [15:0] Ax, Ay, Bx, By, Cx, Cy, Dx, Dy;\n    reg found_eq;\n    reg checking_well;\n    reg [2:0] well_idx;\n    reg is_well;\n    wire [15:0] equal_x, equal_y;\n    reg signed [31:0] orient1, orient2, orient3, orient4;\n    reg angles_opposite;\n\n    // Adjacency matrix\n    reg adj [0:7][0:7];\n\n    // Bipartite variables\n    reg [1:0] colors [0:7];\n    reg [2:0] queue [0:7];\n    reg [2:0] q_head, q_tail;\n    reg [2:0] current_u, current_v;\n    reg [2:0] node_index;\n    reg conflict;\n\n    integer idx, idx2;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            for (idx = 0; idx < 4; idx = idx + 1) begin\n                well_x[idx] <= 16'd0;\n                well_y[idx] <= 16'd0;\n            end\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                pipe_start[idx] <= 3'd0;\n                pipe_end_x[idx] <= 16'd0;\n                pipe_end_y[idx] <= 16'd0;\n                pipeA_x[idx] <= 16'd0;\n                pipeA_y[idx] <= 16'd0;\n                colors[idx] <= 2'd0;\n            end\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                for (idx2 = 0; idx2 < 8; idx2 = idx2 + 1) begin\n                    adj[idx][idx2] <= 1'b0;\n                end\n            end\n            conflict <= 1'b0;\n        end else begin\n            cycle_count <= (state != IDLE) ? cycle_count + 8'd1 : 8'd0;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    conflict <= 1'b0;\n                    if (start) state <= CAPTURE;\n                end\n\n                CAPTURE: begin\n                    well_x[0] <= well_x_0;\n                    well_y[0] <= well_y_0;\n                    well_x[1] <= well_x_1;\n                    well_y[1] <= well_y_1;\n                    well_x[2] <= well_x_2;\n                    well_y[2] <= well_y_2;\n                    well_x[3] <= well_x_3;\n                    well_y[3] <= well_y_3;\n\n                    pipe_start[0] <= pipe_start_0;\n                    pipe_start[1] <= pipe_start_1;\n                    pipe_start[2] <= pipe_start_2;\n                    pipe_start[3] <= pipe_start_3;\n                    pipe_start[4] <= pipe_start_4;\n                    pipe_start[5] <= pipe_start_5;\n                    pipe_start[6] <= pipe_start_6;\n                    pipe_start[7] <= pipe_start_7;\n\n                    pipe_end_x[0] <= pipe_end_x_0;\n                    pipe_end_y[0] <= pipe_end_y_0;\n                    pipe_end_x[1] <= pipe_end_x_1;\n                    pipe_end_y[1] <= pipe_end_y_1;\n                    pipe_end_x[2] <= pipe_end_x_2;\n                    pipe_end_y[2] <= pipe_end_y_2;\n                    pipe_end_x[3] <= pipe_end_x_3;\n                    pipe_end_y[3] <= pipe_end_y_3;\n                    pipe_end_x[4] <= pipe_end_x_4;\n                    pipe_end_y[4] <= pipe_end_y_4;\n                    pipe_end_x[5] <= pipe_end_x_5;\n                    pipe_end_y[5] <= pipe_end_y_5;\n                    pipe_end_x[6] <= pipe_end_x_6;\n                    pipe_end_y[6] <= pipe_end_y_6;\n                    pipe_end_x[7] <= pipe_end_x_7;\n                    pipe_end_y[7] <= pipe_end_y_7;\n\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        case (pipe_start[idx])\n                            3'd0: begin pipeA_x[idx] <= well_x_0; pipeA_y[idx] <= well_y_0; end\n                            3'd1: begin pipeA_x[idx] <= well_x_1; pipeA_y[idx] <= well_y_1; end\n                            3'd2: begin pipeA_x[idx] <= well_x_2; pipeA_y[idx] <= well_y_2; end\n                            3'd3: begin pipeA_x[idx] <= well_x_3; pipeA_y[idx] <= well_y_3; end\n                            default: begin pipeA_x[idx] <= 16'd0; pipeA_y[idx] <= 16'd0; end\n                        endcase\n                    end\n                    state <= INTERSECT;\n                    i <= 3'd0;\n                    j <= 3'd1;\n                end\n\n                INTERSECT: begin\n                    if (cycle_count >= MAX_CYCLES) state <= FINISH;\n                    else if (i < (pipe_count - 1)) begin\n                        if (j < pipe_count) begin\n                            Ax = pipeA_x[i];\n                            Ay = pipeA_y[i];\n                            Bx = pipe_end_x[i];\n                            By = pipe_end_y[i];\n                            Cx = pipeA_x[j];\n                            Cy = pipeA_y[j];\n                            Dx = pipe_end_x[j];\n                            Dy = pipe_end_y[j];\n\n                            // Endpoint checks\n                            found_eq = ((Ax == Cx && Ay == Cy) || (Ax == Dx && Ay == Dy) ||\n                                       (Bx == Cx && By == Cy) || (Bx == Dx && By == Dy));\n                            if (found_eq) begin\n                                // Determine matching point\n                                if (Ax == Cx && Ay == Cy) {equal_x, equal_y} = {Ax, Ay};\n                                else if (Ax == Dx && Ay == Dy) {equal_x, equal_y} = {Ax, Ay};\n                                else if (Bx == Cx && By == Cy) {equal_x, equal_y} = {Bx, By};\n                                else {equal_x, equal_y} = {Bx, By};\n\n                                // Well point check\n                                well_idx <= 3'd0;\n                                is_well <= 1'b0;\n                                checking_well <= 1'b1;\n                                state <= CHECK_WELL;\n                            end else begin\n                                // Cross product calculation\n                                orient1 = ($signed(Bx) - $signed(Ax)) * ($signed(Cy) - $signed(Ay)) -\n                                          ($signed(By) - $signed(Ay)) * ($signed(Cx) - $signed(Ax));\n                                orient2 = ($signed(Bx) - $signed(Ax)) * ($signed(Dy) - $signed(Ay)) -\n                                          ($signed(By) - $signed(Ay)) * ($signed(Dx) - $signed(Ax));\n                                orient3 = ($signed(Dx) - $signed(Cx)) * ($signed(Ay) - $signed(Cy)) -\n                                          ($signed(Dy) - $signed(Cy)) * ($signed(Ax) - $signed(Cx));\n                                orient4 = ($signed(Dx) - $signed(Cx)) * ($signed(By) - $signed(Cy)) -\n                                          ($signed(Dy) - $signed(Cy)) * ($signed(Bx) - $signed(Cx));\n\n                                angles_opposite <= ((orient1[31] != orient2[31]) && (orient3[31] != orient4[31]));\n                                if (angles_opposite) begin\n                                    adj[i][j] <= 1'b1;\n                                    adj[j][i] <= 1'b1;\n                                end\n                                j <= j + 1;\n                            end\n                        end else begin\n                            i <= i + 1;\n                            j <= i + 1;\n                        end\n                    end else state <= BIPARTITE;\n                end\n\n                CHECK_WELL: begin\n                    if (well_idx < well_count) begin\n                        if (well_x[well_idx] == equal_x && well_y[well_idx] == equal_y) is_well <= 1'b1;\n                        well_idx <= well_idx + 1;\n                    end else begin\n                        if (!is_well) begin\n                            adj[i][j] <= 1'b1;\n                            adj[j][i] <= 1'b1;\n                        end\n                        checking_well <= 1'b0;\n                        j <= j + 1;\n                        state <= INTERSECT;\n                    end\n                end\n\n                BIPARTITE: begin\n                    // Initialize colors\n                    for (idx = 0; idx < 8; idx = idx + 1) begin\n                        colors[idx] <= 2'd0;\n                    end\n                    conflict <= 1'b0;\n                    node_index <= 3'd0;\n                    state <= BIPARTITE_LOOP;\n                end\n\n                BIPARTITE_LOOP: begin\n                    if (node_index < pipe_count) begin\n                        if (colors[node_index] == 2'd0) begin\n                            colors[node_index] <= 2'd1;\n                            q_head <= 3'd0;\n                            q_tail <= 3'd1;\n                            queue[0] <= node_index;\n                            state <= BIPARTITE_BFS;\n                        end else node_index <= node_index + 1;\n                    end else state <= FINISH;\n                end\n\n                BIPARTITE_BFS: begin\n                    if (q_head == q_tail || conflict) begin\n                        state <= BIPARTITE_LOOP;\n                        node_index <= node_index + 1;\n                    end else begin\n                        current_u <= queue[q_head];\n                        q_head <= q_head + 1;\n                        current_v <= 3'd0;\n                        state <= BIPARTITE_NEIGHBORS;\n                    end\n                end\n\n                BIPARTITE_NEIGHBORS: begin\n                    if (current_v < pipe_count) begin\n                        if (adj[current_u][current_v]) begin\n                            if (colors[current_v] == 2'd0) begin\n                                colors[current_v] <= (colors[current_u] == 2'd1) ? 2'd2 : 2'd1;\n                                queue[q_tail] <= current_v;\n                                q_tail <= q_tail + 1;\n                            end else if (colors[current_v] == colors[current_u]) begin\n                                conflict <= 1'b1;\n                            end\n                        end\n                        current_v <= current_v + 1;\n                    end else state <= BIPARTITE_BFS;\n                end\n\n                FINISH: begin\n                    result <= !conflict;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule